Given an array arr[], the task is to find the median of this array. The median of an array of size n is defined as the middle element when n is odd and the average of the middle two elements when n is even.Examples: Input: arr[] = [12, 3, 5, 7, 4, 19, 26]Output: 7 Explanation: Sorted sequence of given array arr[] = [3, 4, 5, 7, 12, 19, 26] Since the number of elements is odd, the median is 4th element in the sorted sequence of given array arr[], which is 7Input: arr[] = [12, 3, 5, 7, 4, 26] Output: 6Explanation: Since number of elements are even, median is average of 3rd and 4th element in sorted sequence of given array arr[], which means (5 + 7)/2 = 6Try It Yourself[Naive Approach] By Sorting the Array - O(n log n) Time and O(1) SpaceThe basic idea is to sort the array and check the array size if it is odd then return the middle otherwise return the average of the two middle elements.
            C++

    #include<iostream>
#include<vector>
#include <algorithm>
using namespace std;

double findMedian(vector<int> &arr) {
  	int n = arr.size();

    // First we sort the array
    sort(arr.begin(), arr.end());

    // check for even case
    if (n % 2 != 0)
        return arr[n / 2];

    return (arr[(n - 1) / 2] + arr[n / 2]) / 2.0;
}

int main() {
    vector<int> arr = { 1, 3, 4, 2, 7, 5, 8, 6 };
 	double ans = findMedian(arr);
    cout << ans << endl;
    return 0;
}


