Time Complexity: O(n log n) as we need to sort the array first. Auxiliary Space: O(1)[Expected Approach]: Using Randomized QuickSelect  To find the median of an array, randomly select a pivot element and partition the array using the quicksort technique, placing smaller elements to the left and larger ones to the right. If the pivot lands at the middle index, it is the median. Otherwise, recursively apply this process to the relevant subarray. For even-sized arrays, find the two middle elements and calculate their average.
            C++

    #include "bits/stdc++.h"
using namespace std;

int partition(vector<int>& arr, int l, int r) {
    int lst = arr[r], i = l, j = l;
    while (j < r) {
        if (arr[j] < lst) {
            swap(arr[i], arr[j]);
            i++;
        }
        j++;
    }
    swap(arr[i], arr[r]);
    return i;
}

int randomPartition(vector<int>& arr, int l, int r){
    int n = r - l + 1;
    int pivot = rand() % n;
    swap(arr[l + pivot], arr[r]);
    return partition(arr, l, r);
}

void medianUtil(vector<int>& arr, int l, int r, int k, int& a, int& b) {
    if (l <= r) {
        int partitionIndex = randomPartition(arr, l, r);

	// find the median of odd number element in arr[]
        if (partitionIndex == k) {
            b = arr[partitionIndex];
            if (a != -1) return;
        }
        // a & b as middle element of arr[]
        else if (partitionIndex == k - 1) {
            a = arr[partitionIndex];
            if (b != -1)  return;
        }
        //  index in first half of the arr[]
        if (partitionIndex >= k)
            return medianUtil(arr, l, partitionIndex - 1, k, a, b);

        // find the index in second half of the arr[]
        else
            return medianUtil(arr, partitionIndex + 1, r, k, a, b);
    }
    return;
}

double findMedian(vector<int>& arr) {
    double ans;
  	int  a = -1, b = -1, n = arr.size();

    if (n % 2 == 1) {
        medianUtil(arr, 0, n - 1, n / 2, a, b);
        ans = b;
    } else {
        medianUtil(arr, 0, n - 1, n / 2, a, b);
        ans = (a + b) / 2.0;
    }
   	return ans;
}

int main() {
    vector<int> arr = { 12, 3, 6, 7, 4, 19 };
    cout<<findMedian(arr);
    return 0;
}


